export const ERA_HOMES: readonly EraHome[] = GROUPS.flatMap(({ homes, prefix, ...style }) =>
  homes.map(([kind, form, layout, width, height, capacity]) => ({
    ...style,
    kind,
    wire: kind.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase(),
    label: kind.slice(prefix.length).replace(/([a-z])([A-Z])/g, '$1 $2'),
    form,
    layout,
    footprint: [width, height] as [number, number],
    capacity,
  })),
)

const byKind = new Map(
  ERA_HOMES.flatMap(
    (home) =>
      [
        [home.kind.toLowerCase(), home],
        [home.wire, home],
      ] as const,
  ),
)
export function eraHome(kind: string): EraHome | undefined {
  return byKind.get(kind.toLowerCase())
}
